INSERT INTO metric_definitions (id, code, name, description, unit, category, higher_is_better) VALUES ('ab8e934f-4652-5ca1-87f5-3a5f47cbe429', 'fdv_usd', 'Fully diluted valuation (USD)', 'Max/total supply x price, in USD (CoinGecko).', 'USD', 'market', TRUE);
